export function orb(canvas,getState){const ctx=canvas.getContext('2d'),reduced=matchMedia('(prefers-reduced-motion: reduce)').matches,points=Array.from({length:2300},(_,i)=>{const y=1-2*i/2299,r=Math.sqrt(1-y*y),a=i*2.399963;return [r*Math.cos(a),y,r*Math.sin(a)]});let frame=0;function draw(){const w=canvas.clientWidth,h=canvas.clientHeight;if(!w||!h){if(!reduced)requestAnimationFrame(draw);return}const d=Math.min(devicePixelRatio||1,2);if(canvas.width!==w*d||canvas.height!==h*d){canvas.width=w*d;canvas.height=h*d}ctx.setTransform(d,0,0,d,0,0);ctx.clearRect(0,0,w,h);const t=reduced?0:frame*.0025,state=getState(),busy=['Thinking','Working','Speaking'].includes(state),r=Math.min(w*.25,h*.31),cx=w/2,cy=h*.49;const glow=ctx.createRadialGradient(cx,cy,10,cx,cy,r*1.8);glow.addColorStop(0,'#479ca21a');glow.addColorStop(.5,'#24889514');glow.addColorStop(1,'#24889500');ctx.fillStyle=glow;ctx.fillRect(0,0,w,h);ctx.save();ctx.translate(cx,cy);ctx.strokeStyle='#72b3ba25';ctx.lineWidth=.6;for(let i=0;i<3;i++){ctx.beginPath();ctx.ellipse(0,0,r*(1.22+i*.1),r*(.43+i*.08),t*.12+i*.85-.6,0,Math.PI*2);ctx.stroke()}ctx.setLineDash([1,8]);ctx.beginPath();ctx.arc(0,0,r*1.42,0,Math.PI*2);ctx.stroke();ctx.setLineDash([]);const ps=points.map(([x,y,z],i)=>{const X=x*Math.cos(t)+z*Math.sin(t),Z=-x*Math.sin(t)+z*Math.cos(t);return {x:X,y:y*Math.cos(.3)+Z*Math.sin(.3),z:Z*Math.cos(.3)-y*Math.sin(.3),i}}).sort((a,b)=>a.z-b.z);for(const p of ps){const a=(p.z+1)/2,warp=1+.04*Math.sin(p.y*14+t*(busy?12:3)),px=p.x*r*warp,py=p.y*r*warp;ctx.fillStyle=`rgba(${100+a*50},${160+a*80},${170+a*64},${.08+a*.75})`;ctx.beginPath();ctx.arc(px,py,.35+a*.75,0,Math.PI*2);ctx.fill();if(p.i%2===0&&p.z>.05){ctx.strokeStyle=`rgba(95,202,211,${a*.16})`;ctx.beginPath();ctx.moveTo(px,py);ctx.lineTo(px+Math.sin(p.i+t)*6,py+Math.cos(p.i+t)*6);ctx.stroke()}}ctx.restore();frame++;if(!reduced)requestAnimationFrame(draw)}draw();addEventListener('resize',()=>{if(reduced)draw()});return draw}
export function renderGraph(svg,memories,selected,onSelect,{large=false,zoom=1}={}){const ns='http://www.w3.org/2000/svg',w=large?800:420,h=large?500:235,cx=w/2,cy=h/2,rx=w*.32,ry=h*.34,colors={project:'#b699ee',idea:'#88dfd4',source:'#ceb482',task:'#8cb5e9'};svg.replaceChildren();const g=document.createElementNS(ns,'g');g.setAttribute('transform',`translate(${cx} ${cy}) scale(${zoom}) translate(${-cx} ${-cy})`);svg.append(g);const positions=memories.map((m,i)=>i===0?[cx,cy]:[cx+Math.cos((i-1)/(Math.max(1,memories.length-1))*Math.PI*2-.9)*rx,cy+Math.sin((i-1)/(Math.max(1,memories.length-1))*Math.PI*2-.9)*ry]);const draw=(tag,attrs)=>{const n=document.createElementNS(ns,tag);for(const [k,v]of Object.entries(attrs))n.setAttribute(k,v);return n};const edgeSet=new Set();memories.forEach((m,i)=>{const links=m.links?.length?m.links:i>0?[memories[0].id]:[];links.forEach(id=>{const j=memories.findIndex(m=>m.id===id);if(j<0)return;const key=[i,j].sort().join('-');if(edgeSet.has(key))return;edgeSet.add(key);g.append(draw('line',{x1:positions[i][0],y1:positions[i][1],x2:positions[j][0],y2:positions[j][1],stroke:m.id===selected||id===selected?'#69a6a8':'#3a5068','stroke-width':.8,opacity:.65}))})});memories.forEach((m,i)=>{const [x,y]=positions[i],color=colors[m.kind]||colors.idea,node=draw('g',{class:'node',tabindex:0,role:'button','aria-label':'Explore '+m.title});node.append(draw('circle',{cx:x,cy:y,r:m.id===selected?22:15,fill:color,opacity:m.id===selected?.15:.05}),draw('circle',{cx:x,cy:y,r:i===0?7:4,fill:color}));const label=draw('text',{x,y:y+24,'text-anchor':'middle'});label.textContent=m.title.length>23?m.title.slice(0,21)+'…':m.title;node.append(label);node.onclick=()=>onSelect(m.id);node.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();onSelect(m.id)}};g.append(node)})}
